# Let's find song IDs for all archive songs by searching each title
archive_song_ids = []
for title, artist in archive_songs:
    results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    # Find exact match with title and artist
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            # Check if artist matches
            for art in song['artists']:
                if art['name'].lower() == artist.lower():
                    found = song
                    break
        if found:
            break
    if found:
        archive_song_ids.append(found['song_id'])
        print(f"Found: {title} by {artist} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal found: {len(archive_song_ids)}")

